import $ from 'jquery';
import Ajax from 'core/ajax';
import * as Templates from 'core/templates';
import * as Notification from 'core/notification';
import {get_string as getString} from 'core/str';

/**
 * Read and validate the filter combination from a shareable URL.
 *
 * @param {string} href Full page URL.
 * @param {Set<number>} allowedCourses Courses supplied by the PHP page.
 * @returns {{courseId: number, unread: boolean}} Validated filter state.
 */
export const parseFilters = (href, allowedCourses) => {
    const params = new URL(href).searchParams;
    const rawCourseId = params.get('courseid');
    const requestedCourse = rawCourseId !== null && /^[0-9]+$/.test(rawCourseId)
        ? Number(rawCourseId) : 0;
    const courseId = Number.isSafeInteger(requestedCourse) && allowedCourses.has(requestedCourse)
        ? requestedCourse : 0;
    return {courseId, unread: params.get('unread') === '1'};
};

/**
 * Initialise the cross-course forum feed and preserve filters in browser history.
 *
 * @param {number} initialCourseId Server-validated initial course.
 * @param {boolean} initialUnread Initial unread-only filter.
 */
export const init = (initialCourseId = 0, initialUnread = false) => {
    const root = document.querySelector('[data-region="forum-recent-feed"]');
    if (!root) {
        return;
    }

    const list = root.querySelector('[data-region="feed-items"]');
    const status = root.querySelector('[data-region="feed-status"]');
    const loadMore = root.querySelector('[data-action="feed-more"]');
    const retry = root.querySelector('[data-action="feed-retry"]');
    const allButton = root.querySelector('[data-action="feed-all"]');
    const unreadButton = root.querySelector('[data-action="feed-unread"]');
    const courseSelector = root.querySelector('[data-region="feed-course"]');

    const allowedCourses = new Set(Array.from(courseSelector.options, option => Number(option.value)));
    const initialFilters = parseFilters(window.location.href, allowedCourses);
    const state = {
        courseId: allowedCourses.has(initialFilters.courseId) ? initialFilters.courseId : Number(initialCourseId),
        unread: initialFilters.unread,
        cursor: '',
        hasMore: true,
        loading: false,
        generation: 0,
    };

    // All navigation modes use one canonical state. URL changes from user actions
    // create history entries; popstate restoration never writes new entries.
    const updateControls = () => {
        courseSelector.value = String(state.courseId);
        for (const [button, active] of [[allButton, !state.unread], [unreadButton, state.unread]]) {
            button.setAttribute('aria-pressed', String(active));
            button.classList.toggle('btn-primary', active);
            button.classList.toggle('btn-outline-primary', !active);
        }
    };

    const pushFilters = () => {
        const url = new URL(window.location.href);
        if (state.courseId) {
            url.searchParams.set('courseid', String(state.courseId));
        } else {
            url.searchParams.delete('courseid');
        }
        if (state.unread) {
            url.searchParams.set('unread', '1');
        } else {
            url.searchParams.delete('unread');
        }
        if (url.href !== window.location.href) {
            window.history.pushState({forumRecentFeed: true}, '', url.pathname + url.search + url.hash);
        }
    };

    /**
     * Load a page. Concurrent results from obsolete filter combinations are
     * rendered in a detached container and discarded before touching the list.
     *
     * @param {boolean} reset Whether to reset the result list and cursor.
     * @returns {Promise<void>}
     */
    const load = async(reset = false) => {
        if (!reset && (state.loading || !state.hasMore)) {
            return;
        }
        if (reset) {
            state.generation++;
            state.cursor = '';
            state.hasMore = true;
            list.replaceChildren();
            loadMore.hidden = true;
            retry.hidden = true;
            updateControls();
        }

        const generation = state.generation;
        const request = {courseid: state.courseId, unread: state.unread, cursor: state.cursor};
        const previousCount = list.children.length;
        state.loading = true;
        root.setAttribute('aria-busy', 'true');
        loadMore.disabled = true;
        retry.disabled = true;

        try {
            const loadingText = await getString('recentfeedloading', 'mod_forum');
            if (generation !== state.generation) {
                return;
            }
            status.textContent = loadingText;
            const response = await Ajax.call([{
                methodname: 'mod_forum_get_recent_feed',
                args: request,
            }])[0];
            if (generation !== state.generation) {
                return;
            }

            const [html, js] = await Templates.render('mod_forum/recent_feed_items', response);
            if (generation !== state.generation) {
                return;
            }
            // Do not modify the live feed until asynchronous template rendering
            // finishes and the request still belongs to the selected filters.
            const detached = document.createElement('div');
            await Templates.appendNodeContents($(detached), html, js);
            if (generation !== state.generation) {
                return;
            }
            list.append(...detached.childNodes);
            state.hasMore = Boolean(response.hasmore && response.nextcursor &&
                response.nextcursor !== request.cursor);
            state.cursor = state.hasMore ? response.nextcursor : '';
            loadMore.hidden = !state.hasMore;
            retry.hidden = true;

            const key = list.children.length === 0 && !state.hasMore
                ? 'recentfeedempty' : 'recentfeedloaded';
            const resultText = await getString(key, 'mod_forum', list.children.length);
            if (generation !== state.generation) {
                return;
            }
            status.textContent = resultText;

            if (!reset && previousCount > 0) {
                const firstNew = list.children[previousCount];
                const link = firstNew && firstNew.querySelector('a');
                if (link) {
                    link.focus({preventScroll: true});
                }
            }
        } catch (error) {
            if (generation === state.generation) {
                status.textContent = await getString('recentfeederror', 'mod_forum');
                if (generation === state.generation) {
                    retry.hidden = false;
                    loadMore.hidden = true;
                    Notification.exception(error);
                }
            }
        } finally {
            if (generation === state.generation) {
                state.loading = false;
                root.removeAttribute('aria-busy');
                loadMore.disabled = false;
                retry.disabled = false;
            }
        }
    };

    const select = (courseId, unread) => {
        if (courseId === state.courseId && unread === state.unread) {
            return;
        }
        state.courseId = courseId;
        state.unread = unread;
        pushFilters();
        load(true);
    };

    allButton.addEventListener('click', () => select(state.courseId, false));
    unreadButton.addEventListener('click', () => select(state.courseId, true));
    courseSelector.addEventListener('change', () => {
        const id = Number(courseSelector.value);
        select(allowedCourses.has(id) ? id : 0, state.unread);
    });
    loadMore.addEventListener('click', () => load());
    retry.addEventListener('click', () => load());

    const restoreFilters = () => {
        const previous = parseFilters(window.location.href, allowedCourses);
        state.courseId = previous.courseId;
        state.unread = previous.unread;
        load(true);
    };
    window.addEventListener('popstate', restoreFilters);
    window.addEventListener('pageshow', event => {
        if (event.persisted) {
            restoreFilters();
        }
    });

    updateControls();
    // The first page load does not rewrite the URL or create history entries.
    load(true);
};
